"""Tests for bulk discount functionality."""

from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


@pytest.mark.l4("C-8764baca", "C-e4015f6b", "C-4284227d")
def test_bulk_discount_quantity_threshold_boundary():
    """Test quantities 9, 10, 11 to verify threshold at 10."""
    item_below = LineItem("apple", Decimal("1.00"), 9)
    item_at = LineItem("apple", Decimal("1.00"), 10)
    item_above = LineItem("apple", Decimal("1.00"), 11)

    assert qualifies_for_bulk_discount(item_below) is False
    assert qualifies_for_bulk_discount(item_at) is True
    assert qualifies_for_bulk_discount(item_above) is True


@pytest.mark.l4("C-1caf4da3")
def test_bulk_discount_rounded_to_cents():
    """Test half-up rounding with amounts requiring rounding (e.g., 0.125 -> 0.13)."""
    item = LineItem("apple", Decimal("1.25"), 10)  # total = 12.50, 5% = 0.625
    discount = calculate_bulk_discount(item)
    assert discount == Decimal("0.63")


@pytest.mark.l4("C-8764baca", "C-e4015f6b")
def test_non_qualifying_items_return_zero_discount():
    """Test that items with quantity < 10 return zero discount."""
    item = LineItem("apple", Decimal("100.00"), 9)
    assert calculate_bulk_discount(item) == Decimal("0.00")


@pytest.mark.l4("C-cc0190d6")
def test_cart_bulk_savings_sum_qualifying_items():
    """Test that Cart.bulk_savings() returns sum of qualifying line item discounts."""
    cart = type("Cart", (), {
        "items": [
            LineItem("apple", Decimal("10.00"), 10),  # 5% of 100 = 5.00
            LineItem("pear", Decimal("5.00"), 12),    # 5% of 60 = 3.00
            LineItem("banana", Decimal("1.00"), 9),   # 0
        ]
    })()
    savings = cart.bulk_savings()
    assert savings == Decimal("8.00")


@pytest.mark.l4("C-efd8f9b2", "C-21dee841")
def test_cart_bulk_savings_no_qualifying_returns_zero():
    """Test that cart with no qualifying items returns 0.00."""
    cart = type("Cart", (), {
        "items": [
            LineItem("apple", Decimal("10.00"), 5),
            LineItem("pear", Decimal("5.00"), 9),
        ]
    })()
    savings = cart.bulk_savings()
    assert savings == Decimal("0.00")


@pytest.mark.l4("C-21dee841")
def test_cart_empty_bulk_savings_is_zero():
    """Test that empty cart returns 0.00."""
    cart = type("Cart", (), {"items": []})()
    savings = cart.bulk_savings()
    assert savings == Decimal("0.00")

